final class KruskalMSTTest {
    private KruskalMSTTest() {
    }

    public static void main(String[] args) {
        shouldComputeSampleMst();
        shouldHandleSingleVertexGraph();
        shouldDetectDisconnectedGraphs();
        shouldProtectGraphEdgesFromMutation();
        shouldProtectResultEdgesFromMutation();
        shouldRejectMalformedEdges();
        shouldRejectOutOfRangeVertices();
        System.out.println("All KruskalMST checks passed.");
    }

    private static void shouldComputeSampleMst() {
        Edge[] edges = {
            new Edge(0, 1, 10),
            new Edge(1, 3, 15),
            new Edge(2, 3, 4),
            new Edge(2, 0, 6),
            new Edge(0, 3, 5)
        };

        MstResult result = KruskalMST.minimumSpanningTree(4, edges);
        assertEquals(19, result.totalWeight(), "sample graph");
        assertTrue(result.isSpanningTree(), "sample graph should be connected");
        assertEquals(3, result.edges().length, "sample graph edge count");
        assertEquals(19, KruskalMST.kruskalsMST(4, edges), "legacy sample graph");
        assertEquals(19, KruskalMST.kruskalsMST(4, new int[][] {
            {0, 1, 10}, {1, 3, 15}, {2, 3, 4}, {2, 0, 6}, {0, 3, 5}
        }), "sample graph via raw arrays");
    }

    private static void shouldHandleSingleVertexGraph() {
        MstResult result = KruskalMST.minimumSpanningTree(1, new Edge[0]);
        assertEquals(0, result.totalWeight(), "single-vertex graph");
        assertTrue(result.isSpanningTree(), "single-vertex graph should be connected");
    }

    private static void shouldRejectMalformedEdges() {
        expectIllegalArgument("malformed raw edge", () -> KruskalMST.kruskalsMST(4, new int[][] {{0, 1}}));
        expectIllegalArgument("null edge", () -> KruskalMST.kruskalsMST(4, new Edge[] {null}));
    }

    private static void shouldRejectOutOfRangeVertices() {
        expectIllegalArgument("out-of-range vertex", () -> KruskalMST.kruskalsMST(3, new Edge[] {new Edge(0, 3, 1)}));
    }

    private static void shouldDetectDisconnectedGraphs() {
        MstResult result = KruskalMST.minimumSpanningTree(4, new Edge[] {
            new Edge(0, 1, 2),
            new Edge(2, 3, 3)
        });

        assertEquals(5, result.totalWeight(), "disconnected graph");
        assertFalse(result.isSpanningTree(), "disconnected graph should not be marked as a spanning tree");
        assertEquals(2, result.edges().length, "disconnected graph edge count");
    }

    private static void shouldProtectGraphEdgesFromMutation() {
        WeightedGraph graph = WeightedGraph.of(4, new Edge[] {
            new Edge(0, 1, 10),
            new Edge(1, 3, 15),
            new Edge(2, 3, 4),
            new Edge(2, 0, 6),
            new Edge(0, 3, 5)
        });

        Edge[] exposedEdges = graph.edges();
        exposedEdges[0] = new Edge(9, 9, 9);

        assertEquals(19, KruskalMST.minimumSpanningTree(graph).totalWeight(), "graph edges should be defensive copies");
    }

    private static void shouldProtectResultEdgesFromMutation() {
        MstResult result = KruskalMST.minimumSpanningTree(4, new Edge[] {
            new Edge(0, 1, 10),
            new Edge(1, 3, 15),
            new Edge(2, 3, 4),
            new Edge(2, 0, 6),
            new Edge(0, 3, 5)
        });

        Edge[] exposedEdges = result.edges();
        exposedEdges[0] = new Edge(9, 9, 9);

        assertEquals(3, result.edges().length, "result edges should be defensive copies");
        assertEquals(4, result.edges()[0].weight(), "result edges should not be mutable through accessors");
        assertEquals(19, result.totalWeight(), "result total weight should stay stable");
    }

    private static void assertEquals(int expected, int actual, String scenario) {
        if (expected != actual) {
            throw new AssertionError(
                scenario + ": expected " + expected + " but got " + actual
            );
        }
    }

    private static void expectIllegalArgument(String scenario, Runnable action) {
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            return;
        }

        throw new AssertionError(scenario + ": expected IllegalArgumentException");
    }

    private static void assertTrue(boolean value, String scenario) {
        if (!value) {
            throw new AssertionError(scenario + ": expected true");
        }
    }

    private static void assertFalse(boolean value, String scenario) {
        if (value) {
            throw new AssertionError(scenario + ": expected false");
        }
    }
}

import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;

record WeightedGraph(int vertexCount, List<Edge> edges) {
    WeightedGraph {
        validateVertexCount(vertexCount);
        edges = validateAndCopyEdges(edges, vertexCount);
    }

    static WeightedGraph of(int vertexCount, int[][] rawEdges) {
        return new WeightedGraph(vertexCount, toEdges(rawEdges));
    }

    static WeightedGraph of(int vertexCount, Edge[] edges) {
        return new WeightedGraph(vertexCount, Arrays.asList(edges));
    }

    static WeightedGraph of(int vertexCount, List<Edge> edges) {
        return new WeightedGraph(vertexCount, edges);
    }

    private static void validateVertexCount(int vertexCount) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("vertexCount must be non-negative");
        }
    }

    private static List<Edge> validateAndCopyEdges(List<Edge> edges, int vertexCount) {
        if (edges == null) {
            throw new IllegalArgumentException("edges must not be null");
        }

        List<Edge> copied = new ArrayList<>(edges.size());
        for (int i = 0; i < copied.length; i++) {
            Edge edge = edges.get(i);
            if (edge == null) {
                throw new IllegalArgumentException("edge " + i + " must not be null");
            }
            validateVertexId(edge.from(), vertexCount);
            validateVertexId(edge.to(), vertexCount);
            copied.add(edge);
        }
        return List.copyOf(copied);
    }

    private static void validateVertexId(int vertexId, int vertexCount) {
        if (vertexId < 0 || vertexId >= vertexCount) {
            throw new IllegalArgumentException(
                "vertex id " + vertexId + " is outside the valid range [0, " + (vertexCount - 1) + "]"
            );
        }
    }

    private static List<Edge> toEdges(int[][] rawEdges) {
        if (rawEdges == null) {
            throw new IllegalArgumentException("edges must not be null");
        }

        List<Edge> converted = new ArrayList<>(rawEdges.length);
        for (int i = 0; i < rawEdges.length; i++) {
            int[] edge = rawEdges[i];
            if (edge == null || edge.length != 3) {
                throw new IllegalArgumentException("edge " + i + " must contain exactly three integers");
            }
            converted.add(new Edge(edge[0], edge[1], edge[2]));
        }
        return List.copyOf(converted);
    }
}

